import { parseCommandArgs, parseWaves } from '@terra/contracts';
import { createPlanet, getColonyStock, type CompiledDataLike, PlanetJournal, SimHost, type LedgerPosting, type PlanetState } from '@terra/sim';
import type { ScenarioApi, ScenarioDef } from './_define';
import { SCENARIOS } from './index.generated';

/** Every discovered scenario, sorted by id (generated by `scripts/gen/scenarios.gen.mjs`). */
export const listScenarios = (): readonly ScenarioDef[] => SCENARIOS.map((s) => s.def);

/** Looks a scenario up by its id (`w00`) or its file name (`w00-empty`), case-insensitive. */
export function getScenario(id: string): ScenarioDef | undefined {
  const k = id.toLowerCase();
  return SCENARIOS.find((s) => s.def.id === k || s.file === k)?.def;
}

export interface CreateScenarioOptions {
  /** Id of the new planet (default `pl_dev`). Everything else is identical for the same scenario. */
  readonly planetId?: string;
  /** Wave flags the host runs with; intersected with the scenario's waves (default: the scenario's waves). */
  readonly flags?: Iterable<string>;
  /**
   * Hidden-ground secret (D-38, WE-07). The server passes a fresh `randomUUID()` so clients cannot rebuild the buried
   * layers from the public seed; browser and CLI hosts leave it out.
   */
  readonly worldSalt?: string;
  /** Compiled data the host runs (an experiment's profile); default: the bootstrap tables of the flags. */
  readonly data?: CompiledDataLike;
}

export interface ScenarioPlanet {
  readonly host: SimHost;
  readonly scenario: ScenarioDef;
  /** Ledger postings made while `build` ran (e.g. the landing cargo): the host seeds its journal with them. */
  readonly setupPostings: readonly LedgerPosting[];
}

/** The `api` a scenario's `build` gets for `host` (exported for tests). */
export function apiFor(host: SimHost): ScenarioApi {
  let n = 0;
  return {
    get planet(): PlanetState { return host.state; },
    command(kind, args, colonyIndex = null) {
      const parsed = parseCommandArgs(kind, args);
      if (!parsed.success) throw new Error(`scenario command ${kind} has invalid args: ${parsed.error.message}`);
      const commandId = `scn-${++n}`;
      host.submit({ colonyIndex, source: 'dev', commandId, kind, args: parsed.data });
      const res = host.step(1);
      const o = res.outcomes.find((x) => x.commandId === commandId);
      if (!o || o.code) throw new Error(`scenario command ${kind} rejected: ${o?.code ?? 'not applied'}`);
    },
    settle(ticks) { if (ticks > 0) host.step(ticks); },
  };
}

/** Pure: creates the scenario's planet from its fixed seed (same seed whatever the planet id), then runs `build`. */
export function createScenarioPlanet(id: string, opts: CreateScenarioOptions = {}): ScenarioPlanet {
  const scenario = getScenario(id);
  if (!scenario) throw new Error(`unknown scenario "${id}" (known: ${listScenarios().map((s) => s.id).join(', ')})`);
  const waves = parseWaves(scenario.waves);
  const want = opts.flags ? new Set(opts.flags) : null;
  const flags = waves.list.filter((w) => !want || want.has(w));
  const state = createPlanet({
    type: scenario.planet.type, seed: scenario.seed, planetId: opts.planetId,
    ...(scenario.planet.planetType ? { planetType: scenario.planet.planetType } : {}),
    ...(scenario.planet.radius ? { radius: scenario.planet.radius } : {}),
    ...(opts.worldSalt ? { worldSalt: opts.worldSalt } : {}),
  });
  const host = new SimHost({ flags, ...(opts.data ? { data: opts.data } : {}) });
  host.load(state);
  const setupPostings: LedgerPosting[] = [];
  const off = host.onPostings((p) => { setupPostings.push(...p); });
  scenario.build(host, apiFor(host));
  off();
  if (setupPostings.length === 0 && host.state.colonies.length > 0) {
    const stocks = host.state.colonies.map((_c, i) => getColonyStock(host.state, i));
    setupPostings.push(...PlanetJournal.openingPostings(stocks, host.state.meta.tick, 'system:seed'));
  }
  return { host, scenario, setupPostings };
}
